"use client";
import { useEffect,useRef,useState } from "react";
import { Gift,Users,Check,RefreshCw,Save } from "lucide-react";
import "./referral-panel.css";
type Config={enabled:boolean;inviterCents:number;inviteeCents:number;target:number;days:number;publicApiUrl:string};
type Item={id:string;inviterName:string;inviteeName:string;state:string;progress:number;target:number;deadline:string|null;inviterCents:number;inviteeCents:number;reason:string|null};
type Request=(path:string,method?:string,body?:unknown)=>Promise<any>;
const money=(c:number)=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const labels:Record<string,string>={PAID:'Bônus creditados',ACTIVE:'Em andamento',PENDING_APPROVAL:'Aguardando aprovação',EXPIRED:'Prazo encerrado',REVIEW:'Em análise'};
export default function ReferralPanel({request}:{request:Request}){
 const req=useRef(request);req.current=request;
 const [config,setConfig]=useState<Config|null>(null),[items,setItems]=useState<Item[]>([]),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false);
 const dirty=useRef(false);
 useEffect(()=>{let alive=true;let loading=false;const load=async()=>{if(loading)return;loading=true;try{const d=await req.current('/referrals/admin');if(alive){setItems(d.items);if(!dirty.current)setConfig(d.config);setError('');}}catch{if(alive)setError('Não foi possível atualizar a campanha.');}finally{loading=false;}};void load();const timer=setInterval(()=>void load(),15000);return()=>{alive=false;clearInterval(timer)};},[]);
 function change<K extends keyof Config>(key:K,value:Config[K]){dirty.current=true;setNotice('');setConfig(c=>c?{...c,[key]:value}:c);}
 async function save(e:React.FormEvent){e.preventDefault();if(busy||!config)return;setBusy(true);setError('');try{const c=await req.current('/referrals/admin','PATCH',config);setConfig(c);dirty.current=false;setNotice('Campanha salva. Indicações anteriores mantêm as regras aceitas.');}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar.');}finally{setBusy(false);}}
 return <div className="referralWorkspace"><section className="referralHero"><div><span>PORTO PRIME · CRESCIMENTO</span><h2>Indique & Ganhe</h2><p>Novos motoboys. Recompensas compartilhadas.</p></div><Gift size={48}/></section>{error&&<p role="alert" className="referralError">{error}</p>}{config?<form className="referralCard" onSubmit={save}><div className="referralHeading"><div><h3>Regras da campanha</h3><p>O prazo começa na aprovação do cadastro pelo Admin.</p></div><label className="referralSwitch"><input type="checkbox" checked={config.enabled} onChange={e=>change('enabled',e.target.checked)}/>{config.enabled?'Campanha ativa':'Novos convites pausados'}</label></div><div className="referralFields">{([['inviterCents','Quem indica · R$',0,1000],['inviteeCents','Novo motoboy · R$',0,1000],['target','Entregas válidas',1,1000],['days','Prazo · dias',1,365]] as const).map(([key,label,min,max])=><label key={key}>{label}<input type="number" required min={min} max={max} step={key.endsWith('Cents')?'.01':'1'} value={key.endsWith('Cents')?config[key]/100:config[key]} onChange={e=>change(key,key.endsWith('Cents')?Math.round(Number(e.target.value)*100):Number(e.target.value))}/></label>)}</div><label className="referralUrl">URL HTTPS pública da API para os convites<input type="url" placeholder="https://sua-api.com/api" value={config.publicApiUrl} onChange={e=>change('publicApiUrl',e.target.value)}/><small>Inclua /api. Em testes, use a URL atual do Cloudflare Tunnel seguida de /api. Trocar o túnel invalida links antigos.</small></label><p className="referralNote">Pausar impede novas adesões. Metas, prazos e valores já aceitos são preservados. Os bônus são creditados uma única vez na carteira existente.</p><div className="referralActions"><span role="status">{notice}</span><button disabled={busy} type="submit"><Save size={17}/>{busy?'Salvando…':'Salvar campanha'}</button></div></form>:<p>Carregando campanha…</p>}<section className="referralCard"><div className="referralHeading"><div><h3><Users size={19}/> Indicações</h3><p>Até 200 registros recentes · atualização automática a cada 15 segundos</p></div><RefreshCw size={18}/></div>{items.length===0?<div className="referralEmpty"><Gift size={32}/><p>Os primeiros convites aparecerão aqui.</p></div>:<div className="referralList">{items.map(r=><article key={r.id}><div><strong>{r.inviteeName}</strong><small>Indicado por {r.inviterName}</small><span className={'referralStatus '+r.state}>{labels[r.state]??r.state}</span>{r.reason&&<small>{r.reason}</small>}</div><div><b>{r.progress} / {r.target} entregas</b><progress max={r.target} value={Math.min(r.progress,r.target)}/><small>{r.deadline?'Até '+new Date(r.deadline).toLocaleDateString('pt-BR'):'Prazo inicia após aprovação'}</small></div><div><strong>{money(r.inviterCents+r.inviteeCents)}</strong><small>{money(r.inviterCents)} + {money(r.inviteeCents)}</small>{r.state==='PAID'&&<Check size={18}/>}</div></article>)}</div>}</section></div>;
}

