import pg from 'pg';
if(!process.env.DATABASE_URL)throw new Error('DATABASE_URL ausente no .env da API.');
const client=new pg.Client({connectionString:process.env.DATABASE_URL});
try {
 await client.connect();
 await client.query(readFileSync(new URL('./referrals.sql',import.meta.url),'utf8'));
 console.log('Tabelas de indicacoes instaladas. Nenhum saldo ou pedido existente foi alterado.');
} catch(error) {
 console.error('Falha na migracao de indicacoes. Codigo:',error.code??'DATABASE_ERROR');
 process.exitCode=1;
} finally {await client.end();}

