CREATE TABLE IF NOT EXISTS "CourierReferralCampaign" (
 "id" TEXT PRIMARY KEY DEFAULT 'default', "enabled" BOOLEAN NOT NULL DEFAULT true,
 "inviterCents" INTEGER NOT NULL DEFAULT 3000 CHECK ("inviterCents" BETWEEN 0 AND 100000),
 "inviteeCents" INTEGER NOT NULL DEFAULT 2000 CHECK ("inviteeCents" BETWEEN 0 AND 100000),
 "target" INTEGER NOT NULL DEFAULT 20 CHECK ("target" BETWEEN 1 AND 1000),
 "days" INTEGER NOT NULL DEFAULT 30 CHECK ("days" BETWEEN 1 AND 365),
 "publicApiUrl" TEXT NOT NULL DEFAULT '', "updatedBy" TEXT, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO "CourierReferralCampaign" ("id") VALUES ('default') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS "CourierReferralCode" (
 "courierId" TEXT PRIMARY KEY REFERENCES "CourierProfile"("id") ON DELETE RESTRICT,
 "code" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "CourierReferral" (
 "id" TEXT PRIMARY KEY, "inviterId" TEXT NOT NULL REFERENCES "CourierProfile"("id") ON DELETE RESTRICT,
 "inviteeId" TEXT NOT NULL UNIQUE REFERENCES "CourierProfile"("id") ON DELETE RESTRICT,
 "inviteeCpf" TEXT NOT NULL UNIQUE,
 "inviterCents" INTEGER NOT NULL, "inviteeCents" INTEGER NOT NULL, "target" INTEGER NOT NULL, "days" INTEGER NOT NULL,
 "state" TEXT NOT NULL DEFAULT 'PENDING_APPROVAL' CHECK ("state" IN ('PENDING_APPROVAL','ACTIVE','PAID','EXPIRED','REVIEW')),
 "progress" INTEGER NOT NULL DEFAULT 0, "reason" TEXT,
 "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(), "approvedAt" TIMESTAMPTZ, "deadline" TIMESTAMPTZ,
 "paidAt" TIMESTAMPTZ, "checkedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
 CHECK ("inviterId" <> "inviteeId"));
CREATE INDEX IF NOT EXISTS "CourierReferral_inviter_idx" ON "CourierReferral"("inviterId");
CREATE INDEX IF NOT EXISTS "CourierReferral_worker_idx" ON "CourierReferral"("state","checkedAt");
CREATE TABLE IF NOT EXISTS "CourierReferralAudit" (
 "id" TEXT PRIMARY KEY, "actorId" TEXT NOT NULL, "config" JSONB NOT NULL, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
COMMIT;

