import { BadRequestException } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { referralCode, sameIdentity } from './referral.rules.js';
// Called only inside the transaction that creates a referred courier.
export async function attachReferral(tx:any, userId:string, raw:unknown) {
 const code=referralCode(raw);
 const [cfg]=await tx.$queryRaw`SELECT * FROM "CourierReferralCampaign" WHERE "id"='default' FOR SHARE`;
 if(!cfg?.enabled) throw new BadRequestException('A campanha de indicação está pausada. Remova o código para continuar.');
 const [owner]=await tx.$queryRaw`SELECT c.*,u.phone,u.status FROM "CourierReferralCode" rc JOIN "CourierProfile" c ON c.id=rc."courierId" JOIN "User" u ON u.id=c."userId" WHERE rc.code=${code}`;
 const child=await tx.courierProfile.findUnique({where:{userId},include:{user:true}});
 if(!owner||owner.approvalStatus!=='APPROVED'||owner.status!=='ACTIVE'||!child) throw new BadRequestException('Indicação indisponível. Confira o código.');
 if(sameIdentity({...owner,phone:owner.phone},{...child,phone:child.user.phone}))throw new BadRequestException('Autoindicação não é permitida.');
 const cpf=String(child.document??'').replace(/\D/g,'');
 if(cpf.length!==11)throw new BadRequestException('CPF obrigatório para a indicação.');
 const duplicates=await tx.$queryRaw`SELECT id FROM "CourierProfile" WHERE regexp_replace(COALESCE(document,''),'[^0-9]','','g')=${cpf} AND id<>${child.id} LIMIT 1`;
 if(duplicates.length)throw new BadRequestException('CPF já cadastrado. Indicação não permitida.');
 // Snapshot: later campaign edits cannot change an accepted invitation.
 await tx.$executeRaw`INSERT INTO "CourierReferral" (id,"inviterId","inviteeId","inviteeCpf","inviterCents","inviteeCents",target,days) VALUES (${randomUUID()},${owner.id},${child.id},${cpf},${cfg.inviterCents},${cfg.inviteeCents},${cfg.target},${cfg.days})`;
}
export async function approveReferral(tx:any,courierId:string) {
 await tx.$executeRaw`UPDATE "CourierReferral" SET "approvedAt"=now(),deadline=now()+days*interval '1 day',state='ACTIVE' WHERE "inviteeId"=${courierId} AND "approvedAt" IS NULL AND state='PENDING_APPROVAL'`;
}

import { Body,Controller,Get,Headers,Param,Patch,Header } from '@nestjs/common';
import { ReferralService } from './referral.service.js';
import { referralCode } from './referral.rules.js';
@Controller('referrals')
export class ReferralController {
 constructor(private service:ReferralService){}
 @Get('campaign') async campaign(){const c=await this.service.config();return {enabled:c.enabled,inviterCents:c.inviterCents,inviteeCents:c.inviteeCents,target:c.target,days:c.days};}
 @Get('mine') mine(@Headers('authorization') token?:string){return this.service.mine(token);}
 @Get('admin') admin(@Headers('authorization') token?:string){return this.service.admin(token);}
 @Patch('admin') save(@Body() body:unknown,@Headers('authorization') token?:string){return this.service.save(body,token);}
 @Get('invite/:code') @Header('Content-Type','text/html; charset=utf-8') @Header('Cache-Control','no-store')
 invite(@Param('code') value:string){const code=referralCode(value);return `<!doctype html><html lang="pt-BR"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Indique & Ganhe · Porto Prime</title><body style="font-family:system-ui;background:#eff6f4;color:#073d3b;padding:32px"><main style="max-width:440px;margin:8vh auto;background:white;padding:32px;border-radius:28px"><small>PORTO PRIME · MOTOBOY</small><h1>Um convite para ir mais longe.</h1><p>Cadastre-se como motoboy com o código abaixo. As condições da campanha serão confirmadas no cadastro.</p><h2>${code}</h2><a style="display:block;background:#00615c;color:white;padding:18px;border-radius:16px;text-align:center;text-decoration:none" href="portoprime://invite?code=${code}">Abrir no aplicativo</a><p>Já instalou o Porto Prime? Toque acima e faça seu cadastro. Se ainda não instalou, guarde o código e informe-o no campo de indicação ao se cadastrar.</p></main></body></html>`;}
}

import { Module } from '@nestjs/common';
import { AuthModule } from '../auth/auth.module.js';
import { RealtimeModule } from '../realtime/realtime.module.js';
import { ReferralService } from './referral.service.js';
import { ReferralController } from './referral.controller.js';
@Module({imports:[AuthModule,RealtimeModule],providers:[ReferralService],controllers:[ReferralController]})
export class ReferralModule {}

import { BadRequestException } from '@nestjs/common';
export function referralCode(value: unknown): string {
 if(typeof value !== 'string' || !/^PP[A-Z0-9]{12}$/.test(value.trim().toUpperCase())) throw new BadRequestException('Código de indicação inválido.');
 return value.trim().toUpperCase();
}
export function campaignInput(body: any) {
 if(!body || typeof body.enabled !== 'boolean') throw new BadRequestException('Informe a ativação da campanha.');
 const bounded=(key:string,min:number,max:number)=>{const n=body[key];if(typeof n!=='number'||!Number.isInteger(n)||n<min||n>max)throw new BadRequestException(`Valor inválido: ${key}`);return n;};
 const result={enabled:body.enabled, inviterCents:bounded('inviterCents',0,100000), inviteeCents:bounded('inviteeCents',0,100000), target:bounded('target',1,1000), days:bounded('days',1,365), publicApiUrl:String(body.publicApiUrl??'').trim().replace(/\/$/,'')};
 if(result.publicApiUrl){let u:URL;try{u=new URL(result.publicApiUrl);}catch{throw new BadRequestException('URL pública inválida.');}if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw new BadRequestException('Use a URL HTTPS pública da API, incluindo /api.');}
 return result;
}
export function sameIdentity(a:any,b:any) {
 const digits=(v:unknown)=>String(v??'').replace(/\D/g,'');
 return a.id===b.id || (!!digits(a.document)&&digits(a.document)===digits(b.document)) || (!!digits(a.phone)&&digits(a.phone)===digits(b.phone));
}

import { Injectable, ForbiddenException, Logger, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { randomBytes, randomUUID } from 'node:crypto';
import { PrismaService } from '../prisma/prisma.service.js';
import { AuthService } from '../auth/auth.service.js';
import { RealtimeGateway } from '../realtime/realtime.gateway.js';
import { campaignInput, sameIdentity } from './referral.rules.js';
@Injectable()
export class ReferralService implements OnModuleInit,OnModuleDestroy {
 private timer?:ReturnType<typeof setInterval>; private busy=false;
 private log=new Logger(ReferralService.name);
 constructor(private db:PrismaService,private auth:AuthService,private realtime:RealtimeGateway){}
 onModuleInit(){this.timer=setInterval(()=>void this.sweep(),15000);this.timer.unref();void this.sweep();}
 onModuleDestroy(){if(this.timer)clearInterval(this.timer);}
 async actor(token:string|undefined,role:string){const u=await this.auth.authenticate(token);if(u.role!==role)throw new ForbiddenException();return u;}
 async config(){const rows=await this.db.$queryRaw<any[]>`SELECT * FROM "CourierReferralCampaign" WHERE id='default'`;return rows[0];}
 async mine(token?:string){
  const u=await this.actor(token,'COURIER');const c=await this.db.courierProfile.findUniqueOrThrow({where:{userId:u.id}});
  if(c.approvalStatus!=='APPROVED')throw new ForbiddenException('Aguarde a aprovação do cadastro.');
  const code='PP'+randomBytes(6).toString('hex').toUpperCase();
  await this.db.$executeRaw`INSERT INTO "CourierReferralCode" ("courierId",code) VALUES (${c.id},${code}) ON CONFLICT ("courierId") DO NOTHING`;
  const [own]=await this.db.$queryRaw<any[]>`SELECT code FROM "CourierReferralCode" WHERE "courierId"=${c.id}`;
  const config=await this.config();
  const rows=await this.db.$queryRaw<any[]>`SELECT r.*, CASE WHEN r."inviterId"=${c.id} THEN split_part(u.name,' ',1) ELSE 'Seu convite' END AS name FROM "CourierReferral" r JOIN "CourierProfile" cp ON cp.id=r."inviteeId" JOIN "User" u ON u.id=cp."userId" WHERE r."inviterId"=${c.id} OR r."inviteeId"=${c.id} ORDER BY r."createdAt" DESC LIMIT 200`;
  const totals=await this.db.$queryRaw<any[]>`SELECT COALESCE(SUM(CASE WHEN state='PAID' THEN CASE WHEN "inviterId"=${c.id} THEN "inviterCents" ELSE "inviteeCents" END ELSE 0 END),0)::int AS received, COALESCE(SUM(CASE WHEN state IN ('PENDING_APPROVAL','ACTIVE','REVIEW') THEN CASE WHEN "inviterId"=${c.id} THEN "inviterCents" ELSE "inviteeCents" END ELSE 0 END),0)::int AS pending FROM "CourierReferral" WHERE "inviterId"=${c.id} OR "inviteeId"=${c.id}`;
  return {config,code:own.code,link:config.publicApiUrl?`${config.publicApiUrl}/referrals/invite/${own.code}`:null,totals:totals[0],items:rows.map(r=>({id:r.id,name:r.name,state:r.state,progress:r.progress,target:r.target,days:r.days,deadline:r.deadline,paidAt:r.paidAt,amountCents:r.inviterId===c.id?r.inviterCents:r.inviteeCents}))};
 }
 async admin(token?:string){await this.actor(token,'ADMIN');return {config:await this.config(),items:await this.db.$queryRaw<any[]>`SELECT r.*,u.name AS "inviteeName",v.name AS "inviterName" FROM "CourierReferral" r JOIN "CourierProfile" c ON c.id=r."inviteeId" JOIN "User" u ON u.id=c."userId" JOIN "CourierProfile" p ON p.id=r."inviterId" JOIN "User" v ON v.id=p."userId" ORDER BY r."createdAt" DESC LIMIT 200`};}
 async save(body:unknown,token?:string){const u=await this.actor(token,'ADMIN');const c=campaignInput(body);await this.db.$transaction(async tx=>{
 await tx.$executeRaw`UPDATE "CourierReferralCampaign" SET enabled=${c.enabled},"inviterCents"=${c.inviterCents},"inviteeCents"=${c.inviteeCents},target=${c.target},days=${c.days},"publicApiUrl"=${c.publicApiUrl},"updatedBy"=${u.id},"updatedAt"=now() WHERE id='default'`;
 await tx.$executeRaw`INSERT INTO "CourierReferralAudit" (id,"actorId",config) VALUES (${randomUUID()},${u.id},${JSON.stringify(c)}::jsonb)`;});return this.config();}
 async sweep(){if(this.busy)return;this.busy=true;try{
 const rows=await this.db.$queryRaw<any[]>`SELECT id FROM "CourierReferral" WHERE state IN ('ACTIVE','REVIEW') ORDER BY "checkedAt" ASC LIMIT 100`;
 for(const row of rows){try{const users=await this.process(row.id);for(const userId of users)this.realtime.emitToUser(userId,'wallet.updated',{source:'courier-referral'});if(users.length)this.realtime.emitToRole('ADMIN','wallet.updated',{source:'courier-referral'});}catch(e){this.log.error('Falha ao verificar indicação; próxima execução tentará novamente.');}}
 }catch{this.log.error('Campanha indisponível. Verifique a migração de indicações.');}finally{this.busy=false;}}
 async process(id:string):Promise<string[]>{return this.db.$transaction(async tx=>{
 const [r]=await tx.$queryRaw<any[]>`SELECT * FROM "CourierReferral" WHERE id=${id} FOR UPDATE`;
 if(!r||!['ACTIVE','REVIEW'].includes(r.state)||!r.approvedAt)return [];
 await tx.$executeRaw`UPDATE "CourierReferral" SET "checkedAt"=now() WHERE id=${id}`;
 const a=await tx.courierProfile.findUniqueOrThrow({where:{id:r.inviterId},include:{user:true}});
 const b=await tx.courierProfile.findUniqueOrThrow({where:{id:r.inviteeId},include:{user:true}});
 if(sameIdentity({...a,phone:a.user.phone},{...b,phone:b.user.phone})||String(b.document).replace(/\D/g,'')!==r.inviteeCpf){await tx.$executeRaw`UPDATE "CourierReferral" SET state='REVIEW',reason='Identidade incompatível' WHERE id=${id}`;return [];}
 const valid=await tx.$queryRaw<any[]>`SELECT o.id FROM "Order" o WHERE o."courierId"=${b.id} AND o.status='DELIVERED' AND o."paymentStatus"='PAID' AND o."refundedTotal"=0 AND o."creditedTotal"=0 AND o."canceledAt" IS NULL AND o."deliveredAt">=${r.approvedAt} AND o."deliveredAt"<=${r.deadline} AND o."customerId" NOT IN (${a.userId},${b.userId}) AND EXISTS (SELECT 1 FROM "CourierLedgerEntry" l WHERE l."orderId"=o.id AND l."courierId"=${b.id} AND l.type='DELIVERY_CREDIT') FOR SHARE OF o`;
 const progress=valid.length;
 await tx.$executeRaw`UPDATE "CourierReferral" SET progress=${progress} WHERE id=${id}`;
 if(progress<r.target){await tx.$executeRaw`UPDATE "CourierReferral" SET state=CASE WHEN deadline<now() THEN 'EXPIRED' ELSE 'ACTIVE' END,reason=NULL WHERE id=${id}`;return [];}
 if(a.approvalStatus!=='APPROVED'||b.approvalStatus!=='APPROVED'||a.user.status!=='ACTIVE'||b.user.status!=='ACTIVE'){await tx.$executeRaw`UPDATE "CourierReferral" SET state='REVIEW',reason='Conta sem aprovação ou inativa' WHERE id=${id}`;return [];}
 // Both credits and the paid marker commit together. Unique keys guard repeat workers.
 for(const [courierId,cents,side] of [[a.id,r.inviterCents,'inviter'],[b.id,r.inviteeCents,'invitee']] as const){
 const key=`courier-referral:${r.id}:${side}`;
 const existing=await tx.courierLedgerEntry.findUnique({where:{idempotencyKey:key}});
 if(existing)throw new Error('Crédito inesperado sem conclusão da indicação');
 await tx.courierLedgerEntry.create({data:{courierId,type:'BONUS_CREDIT',amount:cents/100,description:'Indique & Ganhe · Meta concluída',idempotencyKey:key,metadata:{referralId:r.id,source:'courier-referral',side,validOrderIds:valid.map(v=>v.id)}}});
 }
 await tx.$executeRaw`UPDATE "CourierReferral" SET state='PAID',"paidAt"=now(),reason=NULL WHERE id=${id}`;
 return [a.userId,b.userId];
 },{timeout:15000});}
}

import { beforeEach,afterEach,describe,it,expect,vi } from 'vitest';
import { readFileSync } from 'node:fs';
import { PGlite } from '@electric-sql/pglite';
vi.mock('../prisma/prisma.service.js',()=>({PrismaService:class{}}));
vi.mock('../auth/auth.service.js',()=>({AuthService:class{}}));
vi.mock('../realtime/realtime.gateway.js',()=>({RealtimeGateway:class{}}));
import { ReferralService } from './referral.service.js';
import { attachReferral,approveReferral } from './referral.attach.js';
import { campaignInput,referralCode } from './referral.rules.js';
let pg:PGlite,db:any,service:ReferralService,failCredit=false;
const tag=(strings:TemplateStringsArray,values:any[])=>({sql:strings.reduce((s,v,i)=>s+(i?'$'+i:'')+v,''),values});
function adapter(conn:any):any {return {
 $queryRaw:async(strings:TemplateStringsArray,...values:any[])=>{const q=tag(strings,values);return (await conn.query(q.sql,q.values)).rows},
 $executeRaw:async(strings:TemplateStringsArray,...values:any[])=>{const q=tag(strings,values);return (await conn.query(q.sql,q.values)).affectedRows},
 $transaction:(fn:any)=>pg.transaction(tx=>fn(adapter(tx))),
 courierProfile:{findUnique:async({where}:any)=>profile(conn,where),findUniqueOrThrow:async({where}:any)=>{const p=await profile(conn,where);if(!p)throw Error('missing');return p;}},
 courierLedgerEntry:{findUnique:async({where}:any)=>(await conn.query('SELECT * FROM "CourierLedgerEntry" WHERE "idempotencyKey"=$1',[where.idempotencyKey])).rows[0],
 create:async({data:d}:any)=>{if(failCredit&&d.metadata.side==='invitee')throw Error('simulated second credit failure');return (await conn.query('INSERT INTO "CourierLedgerEntry" ("courierId",type,amount,description,"idempotencyKey",metadata) VALUES ($1,$2,$3,$4,$5,$6) RETURNING *',[d.courierId,d.type,d.amount,d.description,d.idempotencyKey,JSON.stringify(d.metadata)])).rows[0];}}
 };}
async function profile(conn:any,where:any){const col=where.id?'id':'userId';const p=(await conn.query(`SELECT * FROM "CourierProfile" WHERE "${col}"=$1`,[where.id??where.userId])).rows[0];if(!p)return null;p.user=(await conn.query('SELECT * FROM "User" WHERE id=$1',[p.userId])).rows[0];return p;}
async function sql(s:string,args:any[]=[]){return (await pg.query(s,args)).rows as any[];}
async function attach(){await db.$transaction((tx:any)=>attachReferral(tx,'ub','PP123456ABCDEF'));return (await sql('SELECT * FROM "CourierReferral"'))[0];}
async function active(){const r=await attach();await db.$transaction((tx:any)=>approveReferral(tx,'b'));await sql(`UPDATE "CourierProfile" SET "approvalStatus"='APPROVED' WHERE id='b'`);await sql(`UPDATE "User" SET status='ACTIVE' WHERE id='ub'`);return (await sql('SELECT * FROM "CourierReferral" WHERE id=$1',[r.id]))[0];}
async function deliveries(n:number){for(let i=0;i<n;i++){await sql(`INSERT INTO "Order" (id,"courierId","customerId",status,"paymentStatus","deliveredAt") VALUES ($1,'b','customer','DELIVERED','PAID',now())`,['o'+i]);await sql(`INSERT INTO "CourierLedgerEntry" ("courierId","orderId",type,amount,"idempotencyKey") VALUES ('b',$1,'DELIVERY_CREDIT',5.5,$2)`,['o'+i,'delivery:'+i]);}}
async function bonuses(){return sql(`SELECT * FROM "CourierLedgerEntry" WHERE type='BONUS_CREDIT' ORDER BY "courierId"`);}
