 CREATE TABLE "CourierLedgerEntry" (id SERIAL PRIMARY KEY,"courierId" TEXT,"orderId" TEXT,type TEXT,amount numeric,description TEXT,"idempotencyKey" TEXT UNIQUE,metadata jsonb);
 INSERT INTO "User" VALUES ('ua','Ana','551100000001','ACTIVE'),('ub','Bruno','551100000002','PENDING'),('uc','Caio','551100000003','ACTIVE');
 INSERT INTO "CourierProfile" VALUES ('a','ua','11111111111','APPROVED'),('b','ub','22222222222','PENDING'),('c','uc','33333333333','APPROVED');`);
 await pg.exec(readFileSync(new URL('../../prisma/referrals.sql',import.meta.url),'utf8'));
