 it('honors snapshots even when new invitations are paused',async()=>{const r=await active();await sql(`UPDATE "CourierReferralCampaign" SET enabled=false,target=99,"inviterCents"=9999`);await deliveries(20);await service.process(r.id);expect((await bonuses()).map(x=>Number(x.amount))).toEqual([30,20]);});
 it('rejects paused campaign enrollment',async()=>{await sql(`UPDATE "CourierReferralCampaign" SET enabled=false`);await expect(attach()).rejects.toThrow();expect(await sql('SELECT * FROM "CourierReferral"')).toHaveLength(0);});
 it('rejects unknown codes',async()=>{await expect(db.$transaction((tx:any)=>attachReferral(tx,'ub','PPFFFFFFFFFFFF'))).rejects.toThrow();});
 it('rejects self referral',async()=>{await expect(db.$transaction((tx:any)=>attachReferral(tx,'ua','PP123456ABCDEF'))).rejects.toThrow();});
