 it('does not count deliveries outside the deadline',async()=>{const r=await active();await deliveries(20);await sql(`UPDATE "Order" SET "deliveredAt"=now()+interval '31 days' WHERE id='o0'`);await service.process(r.id);expect(await bonuses()).toHaveLength(0);});
