 it('a repeated delivery credit never counts an order twice',async()=>{const r=await active();await deliveries(19);await sql(`INSERT INTO "CourierLedgerEntry" ("courierId","orderId",type,amount,"idempotencyKey") VALUES ('b','o0','DELIVERY_CREDIT',5.5,'duplicate-test')`);await service.process(r.id);expect(await bonuses()).toHaveLength(0);expect((await sql('SELECT progress FROM "CourierReferral"'))[0].progress).toBe(19);});
 it('does not count deliveries before approval',async()=>{const r=await active();await deliveries(20);await sql(`UPDATE "Order" SET "deliveredAt"=now()-interval '1 day' WHERE id='o0'`);await service.process(r.id);expect(await bonuses()).toHaveLength(0);});
 it('keeps an existing partial credit untouched for investigation',async()=>{const r=await active();await deliveries(20);await sql(`INSERT INTO "CourierLedgerEntry" ("courierId",type,amount,"idempotencyKey") VALUES ('a','BONUS_CREDIT',30,$1)`,[`courier-referral:${r.id}:inviter`]);await expect(service.process(r.id)).rejects.toThrow();expect(await bonuses()).toHaveLength(1);});
