import 'dart:async';
import 'package:flutter/foundation.dart';
import 'package:app_links/app_links.dart';
import 'package:shared_preferences/shared_preferences.dart';
class ReferralLinks {
 static final latest=ValueNotifier<String>('');
 static const _key='courier_referral_draft';
 static StreamSubscription<Uri>? _subscription;
 static Future<void>? _ready;
 static Future<void> start() => _ready ??= _start();
 static Future<void> _start() async {
  try { final links=AppLinks(); _subscription ??= links.uriLinkStream.listen((uri){unawaited(_capture(uri));},onError:(_){ });
   final initial=await links.getInitialLink();if(initial!=null)await _capture(initial);
  } catch (_) { /* Referral links never prevent normal application startup. */ }
 }
 static Future<void> _capture(Uri uri) async {
  if(uri.scheme!='portoprime'||uri.host!='invite')return;
  final code=(uri.queryParameters['code']??'').toUpperCase();
  if(!RegExp(r'^PP[A-Z0-9]{12}$').hasMatch(code))return;
  try {final p=await SharedPreferences.getInstance();await p.setString(_key,code);latest.value=code;}catch(_){}
 }
 static Future<String> draft() async {try{await start();return (await SharedPreferences.getInstance()).getString(_key)??'';}catch(_){return '';}}
 static Future<void> clear() async {latest.value='';try{await (await SharedPreferences.getInstance()).remove(_key);}catch(_){} }
}

